import os
import stat
import tempfile
import unittest
from unittest.mock import patch

from fastapi.testclient import TestClient

import backend.main as main_module
import backend.yt_cookies as yt_cookies
from backend.main import app

VALID_COOKIES = (
    "# Netscape HTTP Cookie File\n"
    "# This file is generated by yt-dlp.  Do not edit.\n"
    "\n"
    ".youtube.com\tTRUE\t/\tTRUE\t1802593611\t__Secure-3PSID\tg.a000BgExample\n"
    ".youtube.com\tTRUE\t/\tFALSE\t0\twide\t1\n"
    "#HttpOnly_.youtube.com\tTRUE\t/\tTRUE\t1802593611\tSID\tsidexample\n"
    ".google.com\tTRUE\t/\tTRUE\t1802593611\tNID\tnidexample\n"
)


def _client_with_session() -> TestClient:
    client = TestClient(app)
    client.cookies.set("vc_session_token", main_module.SESSION_TOKEN)
    return client


class CookieParsingTest(unittest.TestCase):
    def test_valid_netscape_text_is_accepted(self):
        parsed = yt_cookies.parse_cookie_text(VALID_COOKIES)
        self.assertTrue(parsed["ok"])
        self.assertIsNone(parsed["error"])
        self.assertEqual(parsed["cookie_count"], 4)
        self.assertEqual(parsed["domain_count"], 2)
        self.assertIn("youtube.com", parsed["domains"])
        self.assertTrue(parsed["has_login_cookies"])

    def test_empty_text_is_rejected(self):
        parsed = yt_cookies.parse_cookie_text("   \n\n ")
        self.assertFalse(parsed["ok"])
        self.assertIn("kosong", parsed["error"])

    def test_json_payload_is_rejected(self):
        parsed = yt_cookies.parse_cookie_text('{"cookies": [{"name": "SID"}]}')
        self.assertFalse(parsed["ok"])
        self.assertIn("Netscape", parsed["error"])

    def test_three_column_lines_are_rejected(self):
        parsed = yt_cookies.parse_cookie_text(".youtube.com\tTRUE\t/\n.youtube.com\tTRUE\t/\n")
        self.assertFalse(parsed["ok"])
        self.assertIsNotNone(parsed["error"])

    def test_non_youtube_cookies_are_rejected(self):
        text = ".example.com\tTRUE\t/\tFALSE\t0\tfoo\tbar\n"
        parsed = yt_cookies.parse_cookie_text(text)
        self.assertFalse(parsed["ok"])
        self.assertIn("youtube", parsed["error"].lower())

    def test_without_login_cookies_flag_is_false(self):
        text = ".youtube.com\tTRUE\t/\tFALSE\t0\tPREF\tf6=400\n"
        parsed = yt_cookies.parse_cookie_text(text)
        self.assertTrue(parsed["ok"])
        self.assertFalse(parsed["has_login_cookies"])


class CookieStorageTest(unittest.TestCase):
    def test_save_writes_canonical_file_with_owner_only_permissions(self):
        with tempfile.TemporaryDirectory() as root:
            status = yt_cookies.save_cookie_text(VALID_COOKIES, root=root)
            target = os.path.join(root, yt_cookies.COOKIE_FILENAME)

            self.assertTrue(os.path.isfile(target))
            self.assertTrue(status["exists"])
            self.assertTrue(status["valid"])
            self.assertEqual(status["domain_count"], 2)
            self.assertTrue(status["has_login_cookies"])
            self.assertGreater(status["size_bytes"], 0)

            if os.name != "nt":
                mode = stat.S_IMODE(os.stat(target).st_mode)
                self.assertEqual(mode, 0o600, oct(mode))

    def test_save_rejects_invalid_text(self):
        with tempfile.TemporaryDirectory() as root:
            with self.assertRaises(yt_cookies.CookieFormatError):
                yt_cookies.save_cookie_text("not a cookie file", root=root)
            self.assertFalse(os.path.exists(os.path.join(root, yt_cookies.COOKIE_FILENAME)))

    def test_save_from_file_copies_content(self):
        with tempfile.TemporaryDirectory() as root, tempfile.TemporaryDirectory() as src_dir:
            source = os.path.join(src_dir, "export.txt")
            with open(source, "w", encoding="utf-8") as handle:
                handle.write(VALID_COOKIES)

            status = yt_cookies.save_cookie_from_file(source, root=root)
            self.assertTrue(status["valid"])

    def test_save_from_missing_file_raises(self):
        with tempfile.TemporaryDirectory() as root:
            with self.assertRaises(yt_cookies.CookieFormatError):
                yt_cookies.save_cookie_from_file("/nonexistent/cookies.txt", root=root)

    def test_status_reports_missing_file(self):
        with tempfile.TemporaryDirectory() as root:
            status = yt_cookies.get_cookie_status(root=root)
            self.assertFalse(status["exists"])
            self.assertIsNone(status["path"])
            self.assertEqual(status["filename"], "cookies.txt")

    def test_resolve_prefers_project_root(self):
        with tempfile.TemporaryDirectory() as root:
            yt_cookies.save_cookie_text(VALID_COOKIES, root=root)
            resolved = yt_cookies.resolve_cookie_file(root=root)
            self.assertEqual(resolved, os.path.join(root, yt_cookies.COOKIE_FILENAME))

    def test_resolve_returns_none_without_file(self):
        with tempfile.TemporaryDirectory() as root:
            with patch.object(yt_cookies.os, "getcwd", return_value=root):
                self.assertIsNone(yt_cookies.resolve_cookie_file(root=root))

    def test_delete_removes_file_and_clears_status(self):
        with tempfile.TemporaryDirectory() as root:
            yt_cookies.save_cookie_text(VALID_COOKIES, root=root)
            status = yt_cookies.delete_cookie_file(root=root)

            self.assertFalse(status["exists"])
            self.assertFalse(os.path.exists(os.path.join(root, yt_cookies.COOKIE_FILENAME)))
            self.assertIn(os.path.join(root, yt_cookies.COOKIE_FILENAME), status["removed"])


class CookieTestHelperTest(unittest.TestCase):
    def test_test_cookie_file_without_file(self):
        with tempfile.TemporaryDirectory() as root:
            with patch.object(yt_cookies.os, "getcwd", return_value=root):
                result = yt_cookies.test_cookie_file(root=root)
            self.assertFalse(result["ok"])
            self.assertIn("belum ada", result["error"])

    def test_test_cookie_file_format_only(self):
        with tempfile.TemporaryDirectory() as root:
            yt_cookies.save_cookie_text(VALID_COOKIES, root=root)
            result = yt_cookies.test_cookie_file(root=root, probe=False)
            self.assertTrue(result["ok"])
            self.assertIn("4 cookie", result["message"])

    def test_test_cookie_file_reports_bot_check(self):
        with tempfile.TemporaryDirectory() as root:
            yt_cookies.save_cookie_text(VALID_COOKIES, root=root)
            with patch.object(
                yt_cookies,
                "_probe_with_ytdlp",
                side_effect=RuntimeError(
                    "ERROR: [youtube] xyz: Sign in to confirm you're not a bot"
                ),
            ):
                result = yt_cookies.test_cookie_file(root=root)
            self.assertFalse(result["ok"])
            self.assertIn("bot-check", result["error"])

    def test_test_cookie_file_probe_success(self):
        with tempfile.TemporaryDirectory() as root:
            yt_cookies.save_cookie_text(VALID_COOKIES, root=root)
            with patch.object(
                yt_cookies,
                "_probe_with_ytdlp",
                return_value={"title": "Video Uji", "video_id": "abc", "uploader": "chan"},
            ):
                result = yt_cookies.test_cookie_file(root=root)
            self.assertTrue(result["ok"])
            self.assertIn("Video Uji", result["message"])


class CookieApiTest(unittest.TestCase):
    def test_get_status_requires_session(self):
        with TestClient(app) as client:
            client.cookies.clear()
            self.assertEqual(client.get("/api/youtube-cookies").status_code, 403)

    def test_save_test_delete_roundtrip(self):
        with tempfile.TemporaryDirectory() as root:
            target = os.path.join(root, yt_cookies.COOKIE_FILENAME)
            with patch.object(yt_cookies, "project_root", return_value=root), patch.object(
                main_module, "get_cookie_status", side_effect=lambda: yt_cookies.get_cookie_status(root=root)
            ), patch.object(
                main_module, "save_cookie_text", side_effect=lambda text: yt_cookies.save_cookie_text(text, root=root)
            ), patch.object(
                main_module, "delete_cookie_file", side_effect=lambda: yt_cookies.delete_cookie_file(root=root)
            ):
                with _client_with_session() as client:
                    save_res = client.post("/api/youtube-cookies", json={"text": VALID_COOKIES})
                    self.assertEqual(save_res.status_code, 200)
                    saved = save_res.json()
                    self.assertTrue(saved["valid"])
                    self.assertTrue(os.path.isfile(target))

                    status_res = client.get("/api/youtube-cookies")
                    self.assertEqual(status_res.status_code, 200)
                    self.assertTrue(status_res.json()["exists"])

                    delete_res = client.delete("/api/youtube-cookies")
                    self.assertEqual(delete_res.status_code, 200)
                    self.assertFalse(delete_res.json()["exists"])
                    self.assertFalse(os.path.exists(target))

    def test_save_rejects_invalid_payload(self):
        with _client_with_session() as client:
            self.assertEqual(
                client.post("/api/youtube-cookies", json={"text": "bukan cookies"}).status_code, 400
            )
            self.assertEqual(client.post("/api/youtube-cookies", json={}).status_code, 400)

    def test_save_accepts_file_path(self):
        with tempfile.TemporaryDirectory() as root, tempfile.TemporaryDirectory() as src_dir:
            source = os.path.join(src_dir, "cookies.txt")
            with open(source, "w", encoding="utf-8") as handle:
                handle.write(VALID_COOKIES)

            with patch.object(
                main_module,
                "save_cookie_from_file",
                side_effect=lambda path: yt_cookies.save_cookie_from_file(path, root=root),
            ):
                with _client_with_session() as client:
                    res = client.post("/api/youtube-cookies", json={"path": source})
            self.assertEqual(res.status_code, 200)
            self.assertTrue(res.json()["valid"])

    def test_test_endpoint_returns_probe_result(self):
        with patch.object(
            main_module, "test_cookie_file", return_value={"ok": True, "message": "ok", "error": None}
        ):
            with _client_with_session() as client:
                res = client.post("/api/youtube-cookies/test", json={"probe": False})
        self.assertEqual(res.status_code, 200)
        self.assertTrue(res.json()["ok"])

    def test_status_endpoint_never_leaks_cookie_values(self):
        with tempfile.TemporaryDirectory() as root:
            yt_cookies.save_cookie_text(VALID_COOKIES, root=root)
            with patch.object(
                main_module,
                "get_cookie_status",
                side_effect=lambda: yt_cookies.get_cookie_status(root=root),
            ):
                with _client_with_session() as client:
                    body = client.get("/api/youtube-cookies").text
            self.assertNotIn("g.a000BgExample", body)
            self.assertNotIn("sidexample", body)


class DownloaderCookieIntegrationTest(unittest.TestCase):
    def test_downloader_reuses_shared_resolver(self):
        from backend import downloader

        self.assertIs(downloader.resolve_cookie_file, yt_cookies.resolve_cookie_file)

    def test_resolver_finds_file_saved_from_settings(self):
        from backend import downloader

        with tempfile.TemporaryDirectory() as root:
            yt_cookies.save_cookie_text(VALID_COOKIES, root=root)
            resolved = downloader.resolve_cookie_file(root=root)

        self.assertEqual(resolved, os.path.join(root, yt_cookies.COOKIE_FILENAME))


if __name__ == "__main__":
    unittest.main()
